-- getproperty-api 0036 — release review #4 (D-227): seq dedup is per gateway sequence space, not per meter.
-- A meter's seq is generated by the gateway that reads it; a replaced / re-flashed gateway (new state database) or a
-- meter moved to another gateway restarts at 1. Dedup on (device_id, seq) dropped those readings as duplicates for
-- the 90-day window. The key becomes (device_id, seq_stream, seq) with seq_stream = '<gatewayId>/<seqEpoch>' — the
-- epoch the agent creates with its state database (device protocol 1.1, `TelemetryBatch.seqEpoch`; '-' before).
-- Existing rows get the gateway of their telemetry point and the pre-1.1 epoch '-'.
-- Deviation (schema-design §7.5 row 101): one column on smart.ingest_seq_mark and smart.meter_reading.

ALTER TABLE smart.ingest_seq_mark ADD COLUMN seq_stream text NOT NULL DEFAULT '';
UPDATE smart.ingest_seq_mark m
   SET seq_stream = t.gateway_device_id::text || '/-'
  FROM smart.telemetry_point t
 WHERE t.device_id = m.device_id AND t.seq = m.seq AND t.gateway_device_id IS NOT NULL;
ALTER TABLE smart.ingest_seq_mark DROP CONSTRAINT ingest_seq_mark_pkey;
ALTER TABLE smart.ingest_seq_mark ADD CONSTRAINT ingest_seq_mark_pkey PRIMARY KEY (device_id, seq_stream, seq);
COMMENT ON COLUMN smart.ingest_seq_mark.seq_stream IS 'D-227: the gateway sequence space of the seq — <gatewayId>/<seqEpoch> (''-'' before protocol 1.1).';
COMMENT ON TABLE smart.ingest_seq_mark IS 'D-143 / D-227 dedup window of (meter device, gateway sequence space, seq): purged after 90 days.';

ALTER TABLE smart.meter_reading ADD COLUMN seq_stream text NOT NULL DEFAULT '';
UPDATE smart.meter_reading r
   SET seq_stream = t.gateway_device_id::text || '/-'
  FROM smart.telemetry_point t
 WHERE r.seq IS NOT NULL AND t.device_id = r.device_id AND t.seq = r.seq AND t.time = r.telemetry_time
   AND t.gateway_device_id IS NOT NULL;
DROP INDEX smart.meter_reading_device_id_seq_key;
CREATE UNIQUE INDEX meter_reading_device_id_seq_stream_seq_key ON smart.meter_reading (device_id, seq_stream, seq) WHERE (seq IS NOT NULL);
COMMENT ON COLUMN smart.meter_reading.seq_stream IS 'D-227: the gateway sequence space of seq (IoT readings); '''' for other sources.';
